// Configuração segura para YouTube API
const config = {
  youtube: {
    apiKeys: [
      process.env.REACT_APP_YOUTUBE_API_KEY_1,
      process.env.REACT_APP_YOUTUBE_API_KEY_2,
      process.env.REACT_APP_YOUTUBE_API_KEY_3,
      process.env.REACT_APP_YOUTUBE_API_KEY_4,
      process.env.REACT_APP_YOUTUBE_API_KEY_5,
    ].filter(key => key && key !== process.env.REACT_APP_YOUTUBE_API_KEY_2) // Remove placeholders vazios
  }
};

console.log('API Key:', process.env.REACT_APP_YOUTUBE_API_KEY_1);

// Debug seguro
console.log('🎯 YouTube Config:', {
  hasApiKey: !!config.youtube.apiKey,
  channelId: config.youtube.channelId,
  isDevelopment: process.env.NODE_ENV === 'development'
});

// Se não tem API Key, mostra aviso
if (!config.youtube.apiKey) {
  console.warn('⚠️ YouTube API Key não encontrada. Usando modo fallback.');
}

export default config;
